public CompletableFuture<String> fetchUserDashboard(String userId) {
    return CompletableFuture.supplyAsync(() -> userService.findById(userId), executor)
        .thenCompose(user -> CompletableFuture.supplyAsync(() -> dashboardService.getStats(user), executor))
        .thenApply(stats -> "Dashboard: " + stats.toString())
        .exceptionally(ex -> "Error loading dashboard: " + ex.getMessage());
}
